CREATE PROCEDURE testProc()
BEGIN
	SELECT 42 FROM dual;
END;

select * from t1 union (
    select j from t2
    where (
        j > 10
        or
        j in (
            select j from t1 join t2
        )
    )
);

select * from t1 intersect (
    select j from t2
    where (
        j > 10
        or
        j in (
            select j from t1 join t2
        )
    )
);

select * from t1 except (
    select j from t2
    where (
        j > 10
        or
        j in (
            select j from t1 join t2
        )
    )
);
